+#include "tileimageprovider.h"
+
+#include <QDir>
+#include <QFileInfo>
+#include <QNetworkAccessManager>
+#include <QNetworkReply>
+#include <QNetworkRequest>
+#include <QQuickTextureFactory>
+#include <QStandardPaths>
+#include <QTimer>
+#include <QUrl>
+
+namespace {
+
+class TileImageResponse : public QQuickImageResponse
+{
+public:
+    TileImageResponse(TileImageProvider *provider, const QString &id)
+        : m_provider(provider)
+        , m_id(id)
+    {
+    }
+
+    QQuickTextureFactory *textureFactory() const override
+    {
+        return QQuickTextureFactory::textureFactoryForImage(m_image);
+    }
+
+    QString errorString() const override
+    {
+        return m_error;
+    }
+
+    void cancel() override
+    {
+        m_cancelled = true;
+        QNetworkReply *reply = m_reply;
+        m_reply = nullptr;
+        if (reply) {
+            QObject::disconnect(reply, nullptr, this, nullptr);
+            reply->abort();
+            reply->deleteLater();
+        }
+    }
+
+    void start()
+    {
+        m_network = new QNetworkAccessManager(this);
+        QNetworkRequest request(QUrl(m_provider->tileUrl(m_id)));
+        request.setHeader(QNetworkRequest::UserAgentHeader, m_provider->userAgent());
+        request.setRawHeader("Accept", "image/png,image/*;q=0.8");
+        request.setAttribute(QNetworkRequest::RedirectPolicyAttribute,
+                             QNetworkRequest::NoLessSafeRedirectPolicy);
+        m_reply = m_network->get(request);
+
+        QObject::connect(m_reply, &QNetworkReply::finished, this, [this]() {
+            QNetworkReply *reply = m_reply;
+            m_reply = nullptr;
+            if (!reply || m_done || m_cancelled) {
+                if (reply)
+                    reply->deleteLater();
+                return;
+            }
+
+            const auto finishReply = [&]() {
+                reply->deleteLater();
+            };
+
+            if (reply->error() != QNetworkReply::NoError) {
+                finishReply();
+                finishWithError(QStringLiteral("Map tile download failed: %1")
+                                    .arg(reply->errorString()));
+                return;
+            }
+
+            const int status = reply->attribute(QNetworkRequest::HttpStatusCodeAttribute).toInt();
+            if (status != 200) {
+                finishReply();
+                finishWithError(QStringLiteral("Map tile download failed (HTTP %1).").arg(status));
+                return;
+            }
+
+            QImage image;
+            if (!image.loadFromData(reply->readAll())) {
+                finishReply();
+                finishWithError(QStringLiteral("Map tile data could not be decoded."));
+                return;
+            }
+            finishReply();
+
+            m_image = image;
+            m_provider->cacheImage(m_id, image);
+            const QString path = m_provider->cacheFile(m_id);
+            QDir().mkpath(QFileInfo(path).absolutePath());
+            image.save(path, "PNG");
+
+            m_done = true;
+            emit finished();
+        });
+    }
+
+private:
+    void finishWithError(const QString &error)
+    {
+        m_error = error;
+        if (!m_cancelled && !m_done) {
+            m_done = true;
+            emit finished();
+        }
+    }
+
+    TileImageProvider *m_provider = nullptr;
+    QString m_id;
+    QNetworkAccessManager *m_network = nullptr;
+    QNetworkReply *m_reply = nullptr;
+    QImage m_image;
+    QString m_error;
+    bool m_cancelled = false;
+    bool m_done = false;
+};
+
+class ImmediateTileResponse : public QQuickImageResponse
+{
+public:
+    explicit ImmediateTileResponse(const QImage &image, const QString &error = {})
+        : m_image(image)
+        , m_error(error)
+    {
+        QTimer::singleShot(0, this, [this]() { emit finished(); });
+    }
+
+    QQuickTextureFactory *textureFactory() const override
+    {
+        return QQuickTextureFactory::textureFactoryForImage(m_image);
+    }
+
+    QString errorString() const override
+    {
+        return m_error;
+    }
+
+private:
+    QImage m_image;
+    QString m_error;
+};
+
+} // namespace
+
+TileImageProvider::TileImageProvider()
+    : QQuickAsyncImageProvider()
+    , m_cacheDir(QStandardPaths::writableLocation(QStandardPaths::CacheLocation)
+                 + QStringLiteral("/tiles"))
+    , m_userAgent(QStringLiteral("PoisonLog/0.1 (Qt desktop application)"))
+{
+}
+
+QQuickImageResponse *TileImageProvider::requestImageResponse(const QString &id,
+                                                             const QSize &requestedSize)
+{
+    Q_UNUSED(requestedSize)
+
+    const QStringList parts = id.split(QLatin1Char('/'));
+    if (parts.size() != 3) {
+        return new ImmediateTileResponse({}, QStringLiteral("Invalid map tile request."));
+    }
+    bool zOk = false;
+    bool xOk = false;
+    bool yOk = false;
+    const int z = parts.at(0).toInt(&zOk);
+    const int x = parts.at(1).toInt(&xOk);
+    const int y = parts.at(2).toInt(&yOk);
+    if (!zOk || !xOk || !yOk || z < 0 || z > 22) {
+        return new ImmediateTileResponse({}, QStringLiteral("Invalid map tile coordinates."));
+    }
+
+    const QImage memory = memoryImage(id);
+    if (!memory.isNull())
+        return new ImmediateTileResponse(memory);
+
+    const QString path = cacheFile(id);
+    if (QFileInfo::exists(path)) {
+        QImage cached;
+        if (cached.load(path)) {
+            cacheImage(id, cached);
+            return new ImmediateTileResponse(cached);
+        }
+    }
+
+    auto *response = new TileImageResponse(this, id);
+    response->start();
+    return response;
+}
+
+QString TileImageProvider::tileUrl(const QString &id) const
+{
+    const QStringList parts = id.split(QLatin1Char('/'));
+    if (parts.size() != 3)
+        return {};
+    return QStringLiteral("https://tile.openstreetmap.org/%1/%2/%3.png")
+        .arg(parts.at(0), parts.at(1), parts.at(2));
+}
+
+QString TileImageProvider::cacheFile(const QString &id) const
+{
+    return m_cacheDir + QLatin1Char('/') + id + QStringLiteral(".png");
+}
+
+QImage TileImageProvider::memoryImage(const QString &id) const
+{
+    QMutexLocker locker(&m_memoryMutex);
+    return m_memory.value(id);
+}
+
+void TileImageProvider::cacheImage(const QString &id, const QImage &image)
+{
+    QMutexLocker locker(&m_memoryMutex);
+    if (m_memory.size() > 400)
+        m_memory.clear();
+    m_memory.insert(id, image);
+}
+
+QString TileImageProvider::userAgent() const
+{
+    return m_userAgent;
+}

