```qml
import QtQuick

Item {
    id: root
    clip: true

    property real centerLat: 0
    property real centerLon: 0
    property real groundSpanMeters: 70
    property string attribution: "© OpenStreetMap contributors"
    property bool active: true
    readonly property real effectiveZoom: {
        const mppAtZoom0 = 156543.03392 * Math.cos(centerLat * Math.PI / 180)
        return Math.log(Math.max(1e-9, mppAtZoom0 * Math.max(width, 1) / groundSpanMeters)) / Math.LN2
    }
    readonly property int tileZoom: Math.max(1, Math.min(19, Math.floor(effectiveZoom)))
    readonly property real tileScale: Math.pow(2, effectiveZoom - tileZoom)
    readonly property int tileCount: 1 << tileZoom
    readonly property real tileDisplaySize: 256 * tileScale
    readonly property real worldSize: 256 * Math.pow(2, effectiveZoom)
    readonly property real centerWorldX: lonToWorldX(centerLon, effectiveZoom)
    readonly property real centerWorldY: latToWorldY(centerLat, effectiveZoom)
    readonly property var tileItems: computeTiles()
    property bool tilesReady: false

    function lonToWorldX(lon, zoom) {
        return (normalizeLon(lon) + 180) / 360 * 256 * Math.pow(2, zoom)
    }
    function latToWorldY(lat, zoom) {
        const clamped = Math.max(-85.05112878, Math.min(85.05112878, lat))
        const rad = clamped * Math.PI / 180
        return (1 - Math.log(Math.tan(rad) + 1/Math.cos(rad)) / Math.PI) / 2 * 256 * Math.pow(2, zoom)
    }
    function normalizeLon(lon) { return ((lon + 180) % 360 + 360) % 360 - 180 }
    function computeTiles() {
        if (!active || width <= 0 || height <= 0) return []
        const z = tileZoom
        const scale = tileScale
        const cx = lonToWorldX(centerLon, z)
        const cy = latToWorldY(centerLat, z)
        const halfW = (width / 2) / scale
        const halfH = (height / 2) / scale
        const minX = Math.floor((cx - halfW) / 256)
        const maxX = Math.floor((cx + halfW) / 256)
        const minY = Math.floor((cy - halfH) / 256)
        const maxY = Math.floor((cy + halfH) / 256)
        const n = 1 << z
        const result = []
        for (let ty = minY; ty <= maxY; ++ty) {
            if (ty < 0 || ty >= n) continue
            for (let tx = minX; tx <= maxX; ++tx) {
                const wrappedX = ((tx % n) + n) % n
                result.push({
                    key: z + "/" + tx + "/" + ty + "/" + effect...,
                    sourceX: wrappedX,
                    tileX: tx, tileY: ty,
                    x: (tx * 256 - cx) * scale + width/2,
                    y: (ty * 256 - cy) * scale + height/2
                })
            }
        }
        return result
    }
