    Q_INVOKABLE QString newMapImagePath();
    Q_INVOKABLE void finishMapSetup(const QString &address, double latitude, double longitude,
                                    double groundSpanMeters, const QString &imagePath,
                                    int imageWidth, int imageHeight);

