import QtQuick
import QtQuick.Controls
import QtQuick.Layouts
import PoisonLog 1.0

Frame {
    id: root
    padding: 0

    property var palette: [
        "#2e7d32", "#f9a825", "#ef6c00", "#c62828",
        "#1565c0", "#6a1b9a", "#00838f", "#4e342e"
    ]

    background: Rectangle {
        color: "#ffffff"
        radius: 8
        border.color: "#dfe6e1"
    }

    ColumnLayout {
        anchors.fill: parent
        anchors.margins: 14
        spacing: 10

        RowLayout {
            Layout.fillWidth: true
            Label {
                text: App.mode === "draft" ? "Application details" : "Saved application"
                font.pixelSize: 18
                font.bold: true
                color: "#24382a"
            }
            Item {
                Layout.fillWidth: true
            }
            Label {
                visible: App.mode === "draft"
                text: "Draft"
                color: "#6b7c70"
                font.pixelSize: 11
            }
        }

        StackLayout {
            Layout.fillWidth: true
            Layout.fillHeight: true
            currentIndex: App.mode === "draft" ? 0 : 1

            ColumnLayout {
                id: draftPane
                spacing: 8

                RowLayout {
                    Layout.fillWidth: true
                    spacing: 8

                    Label {
                        text: "Date"
                        Layout.preferredWidth: 48
                        color: "#44554a"
                    }
                    TextField {
                        id: dateField
                        Layout.fillWidth: true
                        text: App.draftDate
                        placeholderText: "YYYY-MM-DD"
                        selectByMouse: true
                        onTextChanged: {
                            if (activeFocus && text !== App.draftDate)
                                App.draftDate = text
                        }
