                    Button {
                        text: "Today"
                        onClicked: {
                            App.draftDate = Qt.formatDate(new Date(), "yyyy-MM-dd")
                            dateField.text = App.draftDate
                        }
                    }
                }

                RowLayout {
                    Layout.fillWidth: true
                    spacing: 8

                    Label {
                        text: "Tag"
                        Layout.preferredWidth: 48
                        color: "#44554a"
                    }
                    TextField {
                        id: tagField
                        Layout.fillWidth: true
                        text: App.draftTag
                        placeholderText: "e.g. glyphosate, fertilizer"
                        selectByMouse: true
                        onTextChanged: {
                            if (activeFocus && text !== App.draftTag)
                                App.draftTag = text
                        }
                    }
                }

                Label {
                    text: "Color"
                    color: "#44554a"
                }

                Flow {
                    Layout.fillWidth: true
                    spacing: 8

                    Repeater {
                        model: root.palette
                        delegate: Rectangle {
                            width: 28
                            height: 28
                            radius: 14
                            color: modelData
                            border.width: App.draftColor.toLowerCase() === modelData ? 3 : 1
                            border.color: App.draftColor.toLowerCase() === modelData
                                          ? "#263238" : "#ffffff"

                            MouseArea {
                                anchors.fill: parent
