mkdir -p /tmp/maptest && cat > /tmp/maptest/CMakeLists.txt <<'EOF'
cmake_minimum_required(VERSION 3.25)
project(maptest LANGUAGES CXX)
set(CMAKE_CXX_STANDARD 20)
set(CMAKE_AUTOMOC ON)
find_package(Qt6 6.12 REQUIRED COMPONENTS Core Gui Qml Quick Network)
add_executable(maptest main.cpp)
target_include_directories(maptest PRIVATE /home/dwight/git/poisonlog/src)
target_link_libraries(maptest PRIVATE /home/dwight/git/poisonlog/build/libpoisonlog_core.a Qt6::Quick Qt6::Network)
EOF
cat > /tmp/maptest/main.cpp <<'EOF'
#include <QGuiApplication>
#include <QImage>
#include <QQuickItem>
#include <QQuickItemGrabResult>
#include <QQuickView>
#include <QTimer>
#include <QDebug>
#include "tileimageprovider.h"

int main(int argc, char **argv)
{
    QGuiApplication app(argc, argv);
    QQuickView view;
    view.engine()->addImageProvider(QStringLiteral("tiles"), new TileImageProvider);
    view.setSource(QUrl::fromLocalFile(QStringLiteral("/home/dwight/git/poisonlog/qml/MapCanvas.qml")));
    if (view.status() != QQuickView::Ready) {
        qWarning() << "view failed" << view.errors();
        return 1;
    }
    view.resize(768, 768);
    view.show();
    QQuickItem *root = view.rootObject();
    if (!root) return 2;
    root->setProperty("centerLat", 38.8976387);
    root->setProperty("centerLon", -77.0365525);
    root->setProperty("active", true);

    int attempts = 0;
    QTimer poll;
    QObject::connect(&poll, &QTimer::timeout, [&]() {
        if (++attempts > 300) {
            qWarning() << "timed out waiting for tiles";
            app.exit(3);
            return;
        }
        if (!root->property("tilesReady").toBool())
            return;
        poll.stop();
        auto result = root->grabToImage(QSize(768, 768));
        QObject::connect(result.data(), &QQuickItemGrabResult::ready, [&, result]() {
            const bool ok = result->saveToFile(QStringLiteral("/tmp/maptest/out.png"));
            QImage img(QStringLiteral("/tmp/maptest/out.png"));
            qInfo() << "saved" << ok << img.size() << img.isNull();
            bool nonBlank = false;
            for (int y = 0; y < img.height() && !nonBlank; y += 32)
                for (int x = 0; x < img.width() && !nonBlank; x += 32)
                    if (img.pixel(x, y) != img.pixel(0, 0)) nonBlank = true;
            qInfo() << "nonBlank" << nonBlank;
            app.exit(ok && nonBlank ? 0 : 4);
        });
    });
    poll.start(100);
    return app.exec();
