             root.panBy(mouse.x - lastX, mouse.y - lastY)
             lastX = mouse.x
             lastY = mouse.y
         }
     }

     Timer {
         interval: 80
         repeat: true
         running: root.active
         onTriggered: root.evaluateTileReadiness()
     }

     Rectangle {
